"""KNOW question bank: questions per skill, authored by teachers, generated by AI or imported, and approved by
a second reviewer before students see them. A KNOW attempt draws a random set from the approved questions."""
from sqlalchemy import Column, ForeignKey, Integer, JSON, String, Text
from sqlalchemy.dialects.postgresql import UUID
from sqlalchemy.orm import relationship

from app.models.base import BaseModel


class Question(BaseModel):
    __tablename__ = "questions"

    skill_id = Column(UUID(as_uuid=True), ForeignKey("skills.id"), nullable=False, index=True)
    text = Column(Text, nullable=False)
    options = Column(JSON, nullable=False)  # 2..6 answer strings
    answer_index = Column(Integer, nullable=False)  # private: never sent to students
    explanation = Column(Text, nullable=True)
    difficulty = Column(String(10), default="L2", nullable=False)  # L1..L5
    source = Column(String(20), default="manual", nullable=False)  # seed | manual | ai | import
    status = Column(String(20), default="draft", nullable=False, index=True)  # draft | approved | rejected
    author_id = Column(UUID(as_uuid=True), ForeignKey("users.id"), nullable=True)
    reviewer_id = Column(UUID(as_uuid=True), ForeignKey("users.id"), nullable=True)
    review_note = Column(String(500), nullable=True)

    skill = relationship("Skill")
